216	        let grammar = ecosystem.version_grammar();
217	        match grammar {
218	            VersionGrammar::SemVer => {
219	                let req = semver::VersionReq::parse(raw).map_err(|e| VersionParseError {
220	                    raw: raw.to_string(),
221	                    grammar,
222	                    message: e.to_string(),
223	                })?;
