225	                    grammar,
226	                    ecosystem,
227	                    req: ParsedVersionReq::SemVer(req),
228	                    raw: raw.to_string(),
229	                })
230	            }
231	            VersionGrammar::Pep440 => {
232	                let req =
233	                    raw.parse::<pep440_rs::VersionSpecifiers>()
