235	                            raw: raw.to_string(),
236	                            grammar,
237	                            message: e.to_string(),
238	                        })?;
239	                // Normalize raw to pep440_rs's canonical rendering so that
240	                // logically-equal specifiers (e.g. ">=1.0.0A1" vs ">=1.0.0a1")
241	                // produce identical raw values and therefore compare == and hash
242	                // equal (derived PartialEq/Eq/Hash include raw).
243	                let canonical = req.to_string();
244	                Ok(VersionReq {
245	                    grammar,
246	                    ecosystem,
247	                    req: ParsedVersionReq::Pep440(req),
248	                    raw: canonical,
249	                })
250	            }
251	            VersionGrammar::Maven => Err(VersionParseError {
252	                raw: raw.to_string(),
253	                grammar,
254	                message: format!("{grammar:?} version requirements not implemented"),
255	            }),
256	        }
257	    }
