126	/// Validates git version against the [`REQUIRED_GIT`] floor.
127	///
128	/// `reported` is the raw `git --version` output (e.g. `"git version 2.39.5"`,
129	/// `"git version 2.39.5.windows.1"` on Git for Windows, which appends a
130	/// non-semver `.windows.N` suffix onto the real version, or
131	/// `"git version 2.39.5-rc1"` for a pre-release build). Only the leading
132	/// `major.minor.patch` triple is parsed, each component truncated to its own
133	/// leading digit run (discarding anything past the first non-digit
134	/// character, e.g. `5-rc1` -> `5`) before being handed to `semver`: passing
135	/// a hyphenated suffix through unstripped would make `semver::VersionReq`
136	/// exclude it from the `>=2.20` floor entirely, since semver requirements
137	/// never match a pre-release version unless the requirement's own comparator
138	/// carries a matching pre-release tag -- a real git build tag has nothing to
139	/// do with that semantics and must not affect whether the floor is met. Any
140	/// dot-separated components after the third (like `.windows.1`) are ignored,
141	/// and a missing `minor`/`patch` is treated as `0`, matching how git itself
142	/// never omits them in practice but keeping this tolerant of a truncated
143	/// report.
144	///
145	/// The actual comparison is delegated to [`semver::VersionReq`] parsing
146	/// [`REQUIRED_GIT`], so the floor is defined in exactly one place instead of
147	/// a separately hand-maintained numeric comparison that could silently drift
148	/// from the constant used in the error message.
149	pub fn check_git_version(reported: &str) -> Result<(), CommandError> {
