131	    /// `Prefixed(Npm, "foo")`, a bare lookup in a graph that contains the
132	    /// same name in two or more ecosystems will produce multiple matches.
133	    /// Callers **must** collect all matches and surface an error when there
134	    /// are two or more — silently taking the first match is the ambiguity
135	    /// bug this function is designed to let callers detect.
136	    ///
137	    /// The canonical example is `resolve_target_package` in
138	    /// `callisto-graph/src/aggregate.rs`: it calls
139	    /// `packages.filter(|p| p.id.matches(id)).collect()`, then returns
140	    /// `Err(GraphError::AmbiguousName)` when the result has two or more
141	    /// entries.  That pattern is the correct way to use `matches()` in any
142	    /// context that may encounter a polyglot workspace.
143	    ///
144	    /// Callers that only need a simple existence check (e.g. "is there at
145	    /// least one package with this name?") may use `.any()` safely — they
146	    /// rely on the aggregation layer to catch and reject ambiguous references
147	    /// before acting on them.
148	    pub fn matches(&self, other: &Self) -> bool {
149	        if self == other {
150	            return true;
151	        }
152	        if self.name() == other.name() {
153	            match (self.ecosystem(), other.ecosystem()) {
154	                (None, _) | (_, None) => true,
155	                (Some(e1), Some(e2)) => e1 == e2,
156	            }
157	        } else {
158	            false
159	        }
160	    }
