453	fn bump_target<D: DependencyResolver>(
454	    id: &PackageId,
455	    sev: Severity,
456	    input: &CascadeInput<'_, D>,
457	) -> Result<Version, GraphError> {
458	    let base = input.base.get(id).cloned().ok_or_else(|| {
459	        GraphError::Manifest(callisto_model::ManifestError::MissingField {
460	            path: PathBuf::from(id.name()),
461	            field: "version",
462	        })
463	    })?;
464	    let versioning: &dyn callisto_format::Versioning = match base.grammar() {
465	        callisto_model::VersionGrammar::Pep440 => &callisto_format::Pep440Versioning,
466	        _ => &callisto_format::SemVerVersioning,
467	    };
468	
469	    if let Some(pre) = input.pre {
470	        if pre.mode == callisto_format::PreMode::Pre {
471	            let pinned_base = pre.initial_versions.get(id.name()).unwrap_or(&base);
472	            versioning
473	                .bump_prerelease(pinned_base, sev, &pre.tag, &base)
474	                .map_err(GraphError::Bump)
475	        } else {
476	            // PreMode::Exit: finalize the current pre-release to a stable version.
477	            // Bumping the on-disk pre-release version (e.g. "1.0.0-alpha.2") with
478	            // any severity that matches the pre-release target strips the tag and
479	            // produces the stable version (e.g. "1.0.0").
480	            versioning.bump(&base, sev).map_err(GraphError::Bump)
481	        }
482	    } else {
483	        versioning.bump(&base, sev).map_err(GraphError::Bump)
484	    }
485	}
