75	    remaining: &[PackageId],
76	    adj: &BTreeMap<PackageId, Vec<PackageId>>,
77	) -> Vec<PackageId> {
78	    use petgraph::algo::tarjan_scc;
79	    use petgraph::graph::DiGraph;
80	
81	    let mut graph = DiGraph::<PackageId, ()>::new();
82	    let mut node_map = BTreeMap::new();
83	    let mut rev_map = BTreeMap::new();
84	
85	    for pkg in remaining {
86	        let idx = graph.add_node(pkg.clone());
87	        node_map.insert(pkg.clone(), idx);
88	        rev_map.insert(idx, pkg.clone());
89	    }
90	
91	    for u in remaining {
92	        if let Some(neighbors) = adj.get(u) {
93	            for v in neighbors {
94	                if let (Some(&u_idx), Some(&v_idx)) = (node_map.get(u), node_map.get(v)) {
95	                    graph.add_edge(u_idx, v_idx, ());
96	                }
97	            }
98	        }
99	    }
100	
101	    let sccs = tarjan_scc(&graph);
102	    for scc in sccs {
